"""Append publication documents and correct only a generated administrative status label."""
import sys,pathlib,hashlib,os
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parent))
from common82_v1 import *
def main():
 before=sha(OUT/'RESULTS82_V1.json');decision=read(OUT/'DECISION82_V1.json');status_path=PROJECT/'CURRENT_RESEARCH_STATUS_V82.md';original=status_path.read_text(encoding='utf-8');dump(OUT/'STATUS_EXPORT_ORIGINAL82_V1.json',dict(utc=utc(),original_content=original,reason='The export CSV loop shadowed its prose-label variable; numerical evidence unchanged'))
 local=decision['summaries'][0];body=f"# C82 current research status\n\nDecision: {decision['decision']}. The simple closure-failure hypothesis was not supported. Local FIM field median NRMSE: closed {local['closed_field_median']:.8f}, open {local['open_field_median']:.8f}; doubled-error pairs {local['pairs_at_least_double']}/8. Its controlled-rollout median is {local['controlled_rollout_median']:.8f}.\n\nSixteen fixed context tasks,64 field outcomes and128 actual controlled rollouts were independently checked. Ordinary local polynomial/RFF models are stronger on this clean polynomial carrier. There is no qualified final research direction. High-dimensional composition, unknown graphs and sensor transfer remain untested. UNICON/GICON/CHOP are newly identified direct prior-art checks for the broader composition route.\n\nThe original-budget GPU campaign remains separate, with no reserved evaluation opened by this cycle. Full payloads remain on the server; GitHub publication only. Overall ACTIVE/UNACHIEVED.\n"
 status_path.write_text(body,encoding='utf-8');old=OUT/'publication_v1';dest=OUT/'publication_v2';dest.mkdir(exist_ok=False);pub=[]
 for row in read(old/'manifest.json')['files']:
  raw=pathlib.Path(row['server_snapshot_file']).read_bytes();assert hashlib.sha256(raw).hexdigest()==row['sha256'];p=dest/'files'/row['path'];p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw);pub.append(dict(row,server_snapshot_file=str(p)))
 for rel in ['README.md','FOLLOWUP_BOUNDARIES82_V1.md','scripts/finalize82_v1.py']:
  raw=(ROOT/rel).read_text(encoding='utf-8-sig').encode();assert all(token.encode() not in raw for token in json.loads(os.environ.get('C82_PRIVATE_EXPORT_PATTERNS_JSON','[]'))),(rel,'private export pattern');p=dest/'files'/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw);pub.append(dict(path=rel,bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest(),git_blob_sha1=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest(),server_snapshot_file=str(p),encoding='utf-8'))
 assert sha(OUT/'RESULTS82_V1.json')==before;dump(dest/'manifest.json',dict(utc=utc(),files=pub,file_count=len(pub),bytes=sum(z['bytes'] for z in pub),prior_snapshot_sha256=sha(old/'manifest.json'),numerical_experiment_unchanged=True,accepted_final_directions=0,overall_goal='ACTIVE_UNACHIEVED',large_data_weights_arrays_included=False,local_payload_files_written=0));print(json.dumps(dict(status='FINAL_SNAPSHOT_READY',files=len(pub),manifest_sha256=sha(dest/'manifest.json'))),flush=True)
if __name__=='__main__':main()
